from pathlib import Path
import subprocess,json,base64,html
from PIL import Image,ImageDraw
r=Path(__file__).resolve().parent
filter="[0:v]scale=640:360,pad=640:392:0:32:color=0x172129,drawtext=text='REFERENCE':x=12:y=8:fontsize=18:fontcolor=white[a];[1:v]scale=640:360,pad=640:392:0:32:color=0x172129,drawtext=text='REVISED PRACTICE':x=12:y=8:fontsize=18:fontcolor=white[b];[a][b]hstack[v]"
subprocess.run(['ffmpeg','-v','error','-y','-i',str(r/'source.mp4'),'-i',str(r/'practice.mp4'),'-filter_complex',filter,'-map','[v]','-map','1:a','-c:v','libx264','-crf','18','-preset','fast','-c:a','aac','-shortest','-movflags','+faststart',str(r/'comparison-v2.mp4')],check=True)
subprocess.run(['ffmpeg','-v','error','-i',str(r/'comparison-v2.mp4'),'-f','null','-'],check=True)
for version in ['before','v2']:
 sheet=Image.new('RGB',(1280,392*4),'#172129')
 for i,t in enumerate([49.4,56.3,69.86,77.29]):
  out=r/f'{version}-pair-{i}.jpg';subprocess.run(['ffmpeg','-v','error','-y','-ss',str(t-1120/30),'-i',str(r/f'comparison-{version}.mp4'),'-frames:v','1',str(out)],check=True);sheet.paste(Image.open(out),(0,i*392))
 sheet.save(r/f'comparison-{version}-sheet.jpg')
notes=[(39.2,'Definition','Restore the full-speaker opening and then the large product card.'),(43.5,'Connections','Shrink the product before revealing data ↔ product ↔ tools.'),(46.,'Question → results → action','Replace generic question/answer boxes with the reference’s large illustrative chat panel. Reproduce the sample product totals and the campaign action.'),(50.45,'Governance','Scale down that same chat panel and enclose it in a green boundary; preserve the example being explained.'),(55.167,'Stack','Change the card plane over 0.53s, then extrude its layers over 0.47s. These durations come from source frame inspection.'),(64.94,'Product hierarchy','Keep Genie One central and in front, Genie Code to the left, Genie Agents to the right. Retain the stack behind them; use the lamp motif consistently.'),(81.53,'Speaker cut','Switch back to the full-size static presenter placeholder rather than holding the finished diagram.')]
(r/'COMPARISON.md').write_text('# Databricks practice — comparison and revision\n\nMatched passage: source 00:37.333–01:23.700, 46.367 seconds. Both sides share one source clock and one narration track.\n\n## What was wrong\n\nThe previous version changed the explanatory representation: it used a generic mechanism diagram where the reference demonstrates a chat interaction. It reversed the product arrangement, placed the sibling cards on a descending diagonal, added an unsupported technical-audience annotation, missed the speaker cut, and used accumulating five-word captions instead of phrase blocks with active-word emphasis.\n\n## Revised\n\n'+'\n'.join(f'- Source {t:.3f}s — **{title}:** {note}' for t,title,note in notes)+'\n\n## Remaining differences\n\nThis is a closer reconstruction, not an exact match. Source is 640×360; the revised version is 1920×1080. Presenter is a fictional static placeholder. Genie vector, shield, database/tool symbols, fonts, textures, arrow shapes, query typing, and easing remain approximations. Caption phrases were regrouped manually with ASR word onsets; they are not frame-certified source captions. The original creator watermark is not copied. The sample chat is reconstructed illustration, not captured product execution. Third-party source/audio is included for this local comparison only; nothing has been published.\n')
uri=lambda name:'data:video/mp4;base64,'+base64.b64encode((r/name).read_bytes()).decode()
buttons=''.join(f'<button data-time="{t-1120/30:.6f}">{t//60:02.0f}:{t%60:05.2f} · {html.escape(title)}</button>' for t,title,note in notes)
page='''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Databricks — source vs reconstruction</title><style>body{margin:0;background:#10191f;color:#eaf1f4;font:16px/1.5 system-ui}main{max-width:1500px;margin:auto;padding:24px}video{width:100%;background:black}button,select{background:#233843;color:white;border:1px solid #5b7480;border-radius:6px;padding:10px;font:inherit;cursor:pointer}nav{display:flex;gap:8px;flex-wrap:wrap;margin:16px 0}p{max-width:1000px;color:#c4d0d6}h1{font-size:30px}#clock{font-variant-numeric:tabular-nums}li{margin:12px 0}</style><main><h1>Reference ↔ revised practice</h1><p>Same source passage, synchronized side by side. Original on the left; reconstruction on the right. One original narration track.</p><video controls playsinline preload="metadata" src="'''+uri('comparison-v2.mp4')+'''"></video><nav><button id="toggle">Show previous attempt</button><button id="back">−1 frame</button><button id="forward">+1 frame</button><select id="speed"><option value=".25">0.25×</option><option value=".5">0.5×</option><option selected value="1">1×</option><option value="2">2×</option></select><span id="clock"></span></nav><nav>'''+buttons+'''</nav><h2>What changed</h2><ul>'''+''.join(f'<li><b>{html.escape(title)}:</b> {html.escape(note)}</li>' for t,title,note in notes)+'''</ul><p>Still approximate: static fictional presenter; icon geometry, fonts, arrow shapes, textures, easing and caption alignment. The sample chat is a reconstructed illustration. Local study; nothing published.</p></main><script>const v=document.querySelector('video');const revised=v.src,previous="'''+uri('comparison-before.mp4')+'''";let isPrevious=false;document.querySelector('#toggle').onclick=()=>{let t=v.currentTime,paused=v.paused;isPrevious=!isPrevious;v.src=isPrevious?previous:revised;v.addEventListener('loadedmetadata',()=>{v.currentTime=t;if(!paused)v.play()},{once:true});document.querySelector('#toggle').textContent=isPrevious?'Show revised attempt':'Show previous attempt'};document.querySelectorAll('[data-time]').forEach(b=>b.onclick=()=>{v.pause();v.currentTime=+b.dataset.time});document.querySelector('#back').onclick=()=>{v.pause();v.currentTime=Math.max(0,v.currentTime-1/30)};document.querySelector('#forward').onclick=()=>{v.pause();v.currentTime=Math.min(v.duration,v.currentTime+1/30)};document.querySelector('#speed').onchange=e=>v.playbackRate=+e.target.value;v.ontimeupdate=()=>document.querySelector('#clock').textContent='Source '+(v.currentTime+37.333333).toFixed(3)+'s';</script>'''
(r/'comparison-review.html').write_text(page)
print('Packaged synchronized before/after comparison and four matched-frame pairs')
